const response = $input.first().json;

try {
  let content = response.choices?.[0]?.message?.content ?? '';
  content = String(content).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = { reply: content || 'No pude procesar tu mensaje.', intent: 'unknown', action: null };
    }
  }

  return [{ json: { reply: parsed.reply || 'No pude procesar tu mensaje.', intent: parsed.intent || 'unknown', action: parsed.action ?? null } }];
} catch (e) {
  return [{ json: { reply: 'No pude procesar tu mensaje.', intent: 'error', action: null } }];
}
